fn handles_empty_quoted_values() {
    let content = "DOUBLE=\"\"\nSINGLE=''";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("DOUBLE"), Some(&"".to_string()));
    assert_eq!(vars.get("SINGLE"), Some(&"".to_string()));
}

#[test]
fn handles_escaped_quotes_in_double_quoted_value() {
    let content = r#"KEY="value with \"escaped\" quotes""#;

    let vars = EnvFileParser::parse(content).unwrap();

    // Parser does not process escape sequences; it strips the outer quotes
    // and preserves the interior literally
    assert_eq!(
        vars.get("KEY"),
        Some(&r#"value with \"escaped\" quotes"#.to_string())
    );
}

#[test]
fn handles_escaped_newline_in_quoted_value() {
    let content = r#"KEY="line1\nline2""#;

    let vars = EnvFileParser::parse(content).unwrap();

    // Escape sequences are preserved as literal characters
    assert_eq!(vars.get("KEY"), Some(&r"line1\nline2".to_string()));
}

#[test]
fn handles_mismatched_quotes() {
    let content = "MIX1=\"value'\nMIX2='value\"";

    let vars = EnvFileParser::parse(content).unwrap();

    // Mismatched quotes are not stripped
    assert_eq!(vars.get("MIX1"), Some(&"\"value'".to_string()));
    assert_eq!(vars.get("MIX2"), Some(&"'value\"".to_string()));
}

#[test]
fn handles_single_quote_mark_only() {
    let content = "KEY=\"";

    let vars = EnvFileParser::parse(content).unwrap();

    // A lone quote is not a pair, so it is preserved
    assert_eq!(vars.get("KEY"), Some(&"\"".to_string()));
}

#[test]
fn preserves_spaces_inside_quotes() {
    let content = "KEY=\"  leading and trailing  \"";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(
        vars.get("KEY"),
        Some(&"  leading and trailing  ".to_string())
    );
}

#[test]
fn preserves_inner_quotes_in_value() {
    let content = r#"KEY="she said 'hello'""#;

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("KEY"), Some(&"she said 'hello'".to_string()));
}

#[test]
fn handles_inline_comment_not_stripped() {
    let content = "KEY=value # this is not stripped";

    let vars = EnvFileParser::parse(content).unwrap();

    // Inline comments are included in the value
    assert_eq!(
        vars.get("KEY"),
        Some(&"value # this is not stripped".to_string())
    );
}

#[test]
fn handles_export_prefix_as_key() {
    let content = "export KEY=value";

    let vars = EnvFileParser::parse(content).unwrap();

    // "export KEY" becomes the key since the parser doesn't strip prefixes
    assert!(vars.get("KEY").is_none());
    assert_eq!(vars.get("export KEY"), Some(&"value".to_string()));
}

#[test]
fn duplicate_keys_last_wins() {
    let content = "KEY=first\nKEY=second\nKEY=third";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("KEY"), Some(&"third".to_string()));
    assert_eq!(vars.len(), 1);
}

#[test]
fn handles_consecutive_equals_signs() {
    let content = "KEY===value";

    let vars = EnvFileParser::parse(content).unwrap();

    assert_eq!(vars.get("KEY"), Some(&"==value".to_string()));
}

