fn parses_only_comments_and_blanks() {
    let content = "# comment 1\n\n# comment 2\n  \n";

    let vars = EnvFileParser::parse(content).unwrap();

    assert!(vars.is_empty());
}

#[test]
fn handles_tabs_in_line() {
    let content = "\tKEY\t=\tvalue\t";

    let vars = EnvFileParser::parse(content).unwrap();

    // Outer line is trimmed, but inner whitespace around = is also trimmed
    assert_eq!(vars.get("KEY"), Some(&"value".to_string()));
}

